=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO completer with edge/level interrupts.
// Implements microarchitecture.md (apb_gpio) against interface_spec.md.
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // Bits 0..N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'h1 << N) - 32'h1);

  // ---------------------------------------------------------------- APB decode
  wire        access  = psel && penable;
  wire [3:0]  idx     = paddr[5:2];
  wire        hi_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire        mapped  = (paddr[1:0] == 2'b00) && hi_zero && (idx <= IDX_INTR_STATUS);

  wire        wr_ok   = access && pwrite && mapped;
  wire        rd_ok   = access && !pwrite && mapped;

  assign pready  = 1'b1;
  assign pslverr = access && (!mapped || (pwrite && (idx == IDX_DATA_IN)));

  wire [31:0] bmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
  wire [31:0] wmask = bmask & PINS;

  // ---------------------------------------------------------------- state
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;
  reg [31:0] rise_en_q;
  reg [31:0] fall_en_q;
  reg [31:0] high_en_q;
  reg [31:0] low_en_q;
  reg [31:0] irq_en_q;
  reg [31:0] status_q;

  // Input widened to 32 bits, zeros above N.
  wire [31:0] gpio_in_w;
  generate
    if (N < 32) begin : g_pad
      assign gpio_in_w = {{(32-N){1'b0}}, gpio_in};
    end else begin : g_full
      assign gpio_in_w = gpio_in;
    end
  endgenerate

  // ---------------------------------------------------------------- next state
  wire we_data_out = wr_ok && (idx == IDX_DATA_OUT);
  wire we_dir      = wr_ok && (idx == IDX_DIR);
  wire we_rise     = wr_ok && (idx == IDX_INTR_RISE);
  wire we_fall     = wr_ok && (idx == IDX_INTR_FALL);
  wire we_high     = wr_ok && (idx == IDX_INTR_HIGH);
  wire we_low      = wr_ok && (idx == IDX_INTR_LOW);
  wire we_irq_en   = wr_ok && (idx == IDX_INTR_ENABLE);
  wire we_status   = wr_ok && (idx == IDX_INTR_STATUS);

  wire [31:0] data_out_d = we_data_out ? ((data_out_q & ~wmask) | (pwdata & wmask)) : data_out_q;
  wire [31:0] dir_d      = we_dir      ? ((dir_q      & ~wmask) | (pwdata & wmask)) : dir_q;
  wire [31:0] rise_en_d  = we_rise     ? ((rise_en_q  & ~wmask) | (pwdata & wmask)) : rise_en_q;
  wire [31:0] fall_en_d  = we_fall     ? ((fall_en_q  & ~wmask) | (pwdata & wmask)) : fall_en_q;
  wire [31:0] high_en_d  = we_high     ? ((high_en_q  & ~wmask) | (pwdata & wmask)) : high_en_q;
  wire [31:0] low_en_d   = we_low      ? ((low_en_q   & ~wmask) | (pwdata & wmask)) : low_en_q;
  wire [31:0] irq_en_d   = we_irq_en   ? ((irq_en_q   & ~wmask) | (pwdata & wmask)) : irq_en_q;

  wire [31:0] rise     = in_q & ~in_prev_q;
  wire [31:0] fall     = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise & rise_en_q) | (fall & fall_en_q)
                         | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  wire [31:0] clear    = we_status ? (pwdata & wmask) : 32'h0;
  // Detection is ORed last: it beats a clear on the same edge.
  wire [31:0] status_d = (status_q & ~clear) | detected;

  // ---------------------------------------------------------------- registers
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0;
      dir_q      <= 32'h0;
      in_q       <= 32'h0;
      in_prev_q  <= 32'h0;
      rise_en_q  <= 32'h0;
      fall_en_q  <= 32'h0;
      high_en_q  <= 32'h0;
      low_en_q   <= 32'h0;
      irq_en_q   <= 32'h0;
      status_q   <= 32'h0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      in_q       <= gpio_in_w;
      in_prev_q  <= in_q;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      irq_en_q   <= irq_en_d;
      status_q   <= status_d;
    end
  end

  // ---------------------------------------------------------------- outputs
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & irq_en_q);

  always @* begin
    prdata = 32'h0;
    if (rd_ok) begin
      case (idx)
        IDX_DATA_OUT:    prdata = data_out_q;
        IDX_DIR:         prdata = dir_q;
        IDX_DATA_IN:     prdata = in_q;
        IDX_INTR_RISE:   prdata = rise_en_q;
        IDX_INTR_FALL:   prdata = fall_en_q;
        IDX_INTR_HIGH:   prdata = high_en_q;
        IDX_INTR_LOW:    prdata = low_en_q;
        IDX_INTR_ENABLE: prdata = irq_en_q;
        IDX_INTR_STATUS: prdata = status_q;
        default:         prdata = 32'h0;
      endcase
    end
  end

endmodule
=== END FILE ===
