`timescale 1ns/1ps
// Self-checking testbench for apb_gpio, at N=8 and N=32.
module apb_gpio_tb;

  reg         pclk = 1'b0;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg         sel;          // 0: N=8 instance, 1: N=32 instance
  reg  [7:0]  gin8;
  reg  [31:0] gin32;

  wire [31:0] prdata8, prdata32;
  wire        pready8, pready32, pslverr8, pslverr32;
  wire [7:0]  gout8, goe8;
  wire [31:0] gout32, goe32;
  wire        irq8, irq32;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr),
    .psel(psel & ~sel), .penable(penable), .pwrite(pwrite),
    .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
    .pready(pready8), .pslverr(pslverr8),
    .gpio_in(gin8), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr),
    .psel(psel & sel), .penable(penable), .pwrite(pwrite),
    .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
    .pready(pready32), .pslverr(pslverr32),
    .gpio_in(gin32), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
  );

  wire [31:0] cur_prdata  = sel ? prdata32  : prdata8;
  wire        cur_pready  = sel ? pready32  : pready8;
  wire        cur_pslverr = sel ? pslverr32 : pslverr8;
  wire [31:0] cur_out     = sel ? gout32 : {24'h0, gout8};
  wire [31:0] cur_oe      = sel ? goe32  : {24'h0, goe8};
  wire        cur_irq     = sel ? irq32  : irq8;

  reg  [31:0] P;            // pins mask of the active instance
  integer     passed;
  integer     failed;
  reg  [8*64-1:0] nonce;

  always #5 pclk = ~pclk;

  // ---------------------------------------------------------------- checks
  task chk32(input [31:0] got, input [31:0] exp, input integer id);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("check %0d (N=%0d): got %h, expected %h", id, sel ? 32 : 8, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task chk1(input got, input exp, input integer id);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("check %0d (N=%0d): got %b, expected %b", id, sel ? 32 : 8, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  // ---------------------------------------------------------------- stimulus
  // All tasks are entered just after a falling edge and leave just after one.
  task idle(input integer n);
    begin
      repeat (n) @(negedge pclk);
    end
  endtask

  task set_in(input [31:0] v);
    begin
      if (sel) gin32 = v;
      else     gin8  = v[7:0];
    end
  endtask

  task apb_write(input [7:0] a, input [31:0] d, input [3:0] s, input exp_err, input integer id);
    begin
      psel = 1'b1; penable = 1'b0; paddr = a; pwrite = 1'b1; pwdata = d; pstrb = s;
      #1;
      chk1(cur_pslverr, 1'b0, id);        // setup: no error
      chk32(cur_prdata, 32'h0, id);       // setup: prdata zero
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(cur_pready, 1'b1, id);
      chk1(cur_pslverr, exp_err, id);
      chk32(cur_prdata, 32'h0, id);
      @(negedge pclk);                    // write committed on the rising edge
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
    end
  endtask

  task apb_read(input [7:0] a, input [31:0] exp_d, input exp_err, input integer id);
    begin
      psel = 1'b1; penable = 1'b0; paddr = a; pwrite = 1'b0; pwdata = 32'h0; pstrb = 4'h0;
      #1;
      chk1(cur_pslverr, 1'b0, id);
      chk32(cur_prdata, 32'h0, id);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(cur_pready, 1'b1, id);
      chk1(cur_pslverr, exp_err, id);
      chk32(cur_prdata, exp_d, id);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0;
    end
  endtask

  task do_reset;
    begin
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
      paddr = 8'h0; pwdata = 32'h0;
      presetn = 1'b0;
      repeat (2) @(negedge pclk);
      chk32(cur_out, 32'h0, 50);
      chk32(cur_oe, 32'h0, 51);
      chk1(cur_irq, 1'b0, 52);
      presetn = 1'b1;
    end
  endtask

  // Read/write register with partial strobes and bits above N.
  task test_rw(input [7:0] a, input integer id);
    reg [31:0] m;
    begin
      apb_write(a, 32'hFFFF_FFFF, 4'hF, 1'b0, id);
      m = P;
      apb_read(a, m, 1'b0, id + 1);
      if (a == 8'h00) chk32(cur_out, m, id + 1);
      if (a == 8'h04) chk32(cur_oe, m, id + 1);

      apb_write(a, 32'h0000_0000, 4'b0010, 1'b0, id + 2);
      m = m & ~32'h0000_FF00;
      apb_read(a, m, 1'b0, id + 3);
      if (a == 8'h00) chk32(cur_out, m, id + 3);
      if (a == 8'h04) chk32(cur_oe, m, id + 3);

      apb_write(a, 32'h1234_5678, 4'b1001, 1'b0, id + 4);
      m = (m & ~32'hFF00_00FF) | (32'h1234_5678 & 32'hFF00_00FF & P);
      apb_read(a, m, 1'b0, id + 5);
      if (a == 8'h00) chk32(cur_out, m, id + 5);
      if (a == 8'h04) chk32(cur_oe, m, id + 5);

      apb_write(a, 32'h0000_0000, 4'b0000, 1'b0, id + 6);   // no strobes
      apb_read(a, m, 1'b0, id + 7);

      apb_write(a, 32'h0000_0000, 4'hF, 1'b0, id + 8);
      apb_read(a, 32'h0, 1'b0, id + 9);
      if (a == 8'h00) chk32(cur_out, 32'h0, id + 9);
      if (a == 8'h04) chk32(cur_oe, 32'h0, id + 9);
    end
  endtask

  task run_suite;
    integer k;
    begin
      P = sel ? 32'hFFFF_FFFF : 32'h0000_00FF;
      set_in(32'h0);
      do_reset;

      // Reset values.
      for (k = 0; k < 9; k = k + 1)
        apb_read({k[5:0], 2'b00}, 32'h0, 1'b0, 20 + k);
      chk32(cur_out, 32'h0, 30);
      chk32(cur_oe, 32'h0, 31);
      chk1(cur_irq, 1'b0, 32);

      // Read/write registers.
      test_rw(8'h00, 100);
      test_rw(8'h04, 110);
      test_rw(8'h0C, 120);
      test_rw(8'h10, 130);
      test_rw(8'h14, 140);
      test_rw(8'h18, 150);
      // INTR_LOW with all pins low set every status bit (masked, irq low).
      apb_read(8'h20, P, 1'b0, 170);
      chk1(cur_irq, 1'b0, 171);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 172);
      apb_read(8'h20, 32'h0, 1'b0, 173);
      test_rw(8'h1C, 160);

      // DATA_IN: sampled, read only.
      set_in(32'hA5C3_5A3C & P);
      apb_read(8'h08, 32'hA5C3_5A3C & P, 1'b0, 200);
      apb_write(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1, 201);
      apb_read(8'h08, 32'hA5C3_5A3C & P, 1'b0, 202);
      // Input read with outputs enabled is still the pin input.
      apb_write(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0, 203);
      apb_write(8'h00, 32'h0F0F_0F0F, 4'hF, 1'b0, 204);
      chk32(cur_out, 32'h0F0F_0F0F & P, 205);
      chk32(cur_oe, P, 206);
      apb_read(8'h08, 32'hA5C3_5A3C & P, 1'b0, 207);
      apb_write(8'h04, 32'h0, 4'hF, 1'b0, 208);
      apb_write(8'h00, 32'h0, 4'hF, 1'b0, 209);
      set_in(32'h0);
      idle(2);

      // PSLVERR policy and decode.
      apb_read(8'h24, 32'h0, 1'b1, 300);
      apb_read(8'h01, 32'h0, 1'b1, 301);
      apb_read(8'h02, 32'h0, 1'b1, 302);
      apb_read(8'h23, 32'h0, 1'b1, 303);
      apb_read(8'h3C, 32'h0, 1'b1, 304);
      apb_read(8'h40, 32'h0, 1'b1, 305);
      apb_read(8'h80, 32'h0, 1'b1, 306);
      apb_read(8'hFC, 32'h0, 1'b1, 307);
      apb_write(8'h00, 32'hFFFF_FFFF, 4'hF, 1'b0, 310);
      apb_write(8'h40, 32'h0, 4'hF, 1'b1, 311);   // would alias DATA_OUT
      apb_write(8'h01, 32'h0, 4'hF, 1'b1, 312);
      apb_write(8'h24, 32'h0, 4'hF, 1'b1, 313);
      apb_write(8'hC0, 32'h0, 4'hF, 1'b1, 314);
      apb_read(8'h00, P, 1'b0, 315);
      chk32(cur_out, P, 316);
      apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1, 317); // would alias DIR
      apb_read(8'h04, 32'h0, 1'b0, 318);
      apb_write(8'h00, 32'h0, 4'hF, 1'b0, 319);

      // Rising edge, mask, partial clear, race.
      set_in(32'h0);
      idle(3);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 400);
      apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF, 1'b0, 401);
      set_in(32'h8000_000D & P);
      idle(2);
      apb_read(8'h20, 32'h8000_000D & P, 1'b0, 402);
      chk1(cur_irq, 1'b0, 403);                       // masked
      apb_write(8'h1C, 32'h0000_0004, 4'hF, 1'b0, 404);
      chk1(cur_irq, 1'b1, 405);                       // unmasking pending
      apb_write(8'h20, 32'h0000_0005, 4'hF, 1'b0, 406);
      apb_read(8'h20, 32'h8000_0008 & P, 1'b0, 407);
      chk1(cur_irq, 1'b0, 408);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'h0, 1'b0, 409);
      apb_read(8'h20, 32'h8000_0008 & P, 1'b0, 410);
      apb_write(8'h20, 32'h0000_0008, 4'b0010, 1'b0, 411);
      apb_read(8'h20, 32'h8000_0008 & P, 1'b0, 412);
      apb_write(8'h20, 32'h8000_0000, 4'b1000, 1'b0, 413);
      apb_read(8'h20, 32'h0000_0008 & P, 1'b0, 414);
      apb_write(8'h20, 32'h0000_0008, 4'b0001, 1'b0, 415);
      apb_read(8'h20, 32'h0, 1'b0, 416);
      idle(3);
      apb_read(8'h20, 32'h0, 1'b0, 417);              // edge fires once
      set_in(32'h8000_000F & P);                      // bit 1 rises ...
      apb_write(8'h20, 32'h0000_0002, 4'hF, 1'b0, 418); // ... on the clear's edge
      apb_read(8'h20, 32'h0000_0002, 1'b0, 419);
      set_in(32'h8000_001F & P);                      // one-cycle pulse, bit 4
      @(negedge pclk);
      set_in(32'h8000_000F & P);
      idle(2);
      apb_read(8'h20, 32'h0000_0012 & P, 1'b0, 420);
      apb_write(8'h1C, 32'h0000_0010, 4'hF, 1'b0, 421);
      chk1(cur_irq, 1'b1, 422);
      apb_write(8'h1C, 32'h0, 4'hF, 1'b0, 423);
      chk1(cur_irq, 1'b0, 424);
      apb_write(8'h0C, 32'h0, 4'hF, 1'b0, 425);
