      // Falling edge, and both edges on one bit.
      apb_write(8'h10, 32'hFFFF_FFFF, 4'hF, 1'b0, 500);
      set_in(32'h0000_0005 & P);
      idle(2);
      apb_read(8'h20, 32'h8000_000A & P, 1'b0, 501);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 502);
      apb_read(8'h20, 32'h0, 1'b0, 503);
      apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF, 1'b0, 504);
      set_in(32'h0000_0045 & P);
      idle(2);
      apb_read(8'h20, 32'h0000_0040 & P, 1'b0, 505);
      apb_write(8'h20, 32'h0000_0040, 4'hF, 1'b0, 506);
      apb_read(8'h20, 32'h0, 1'b0, 507);
