      apb_write(8'h10, 32'h0, 4'hF, 1'b0, 510);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 511);
      apb_read(8'h20, 32'h0, 1'b0, 512);

      // High level: sets again after a clear while it holds.
      apb_write(8'h14, 32'hFFFF_FFFF, 4'hF, 1'b0, 600);
      idle(1);
      apb_read(8'h20, 32'h0000_0005 & P, 1'b0, 601);
      apb_write(8'h20, 32'h0000_0001, 4'hF, 1'b0, 602);
      apb_read(8'h20, 32'h0000_0005 & P, 1'b0, 603);
      set_in(32'h0000_0004 & P);
      apb_write(8'h20, 32'h0000_0001, 4'hF, 1'b0, 604);
      apb_read(8'h20, 32'h0000_0004 & P, 1'b0, 605);
      apb_write(8'h20, 32'h0000_0004, 4'hF, 1'b0, 606);
      apb_read(8'h20, 32'h0000_0004 & P, 1'b0, 607);
      apb_write(8'h14, 32'h0, 4'hF, 1'b0, 608);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 609);
      apb_read(8'h20, 32'h0, 1'b0, 610);

      // Low level, with irq.
      apb_write(8'h18, 32'hFFFF_FFFF, 4'hF, 1'b0, 700);
      idle(1);
      apb_read(8'h20, P & ~32'h0000_0004, 1'b0, 701);
      apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0, 702);
      chk1(cur_irq, 1'b1, 703);
      apb_write(8'h18, 32'h0, 4'hF, 1'b0, 704);
      apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0, 705);
      apb_read(8'h20, 32'h0, 1'b0, 706);
      chk1(cur_irq, 1'b0, 707);
      apb_write(8'h1C, 32'h0, 4'hF, 1'b0, 708);

      // Reset again with state set.
      apb_write(8'h00, 32'hFFFF_FFFF, 4'hF, 1'b0, 800);
      apb_write(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0, 801);
      apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF, 1'b0, 802);
