      do_reset;
      for (k = 0; k < 9; k = k + 1)
        apb_read({k[5:0], 2'b00}, 32'h0, 1'b0, 820 + k);
      chk32(cur_out, 32'h0, 830);
      chk32(cur_oe, 32'h0, 831);
      chk1(cur_irq, 1'b0, 832);
    end
